  &lt;span class="nt"&gt;-d&lt;/span&gt; &lt;span class="s1"&gt;'{
    "model": "glm-5.2",
    "messages": [{"role": "user", "content": "Review this diff for race conditions."}]
  }'&lt;/span&gt;
